import { compare, hash } from "bcryptjs";
import { randomUUID } from "node:crypto";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// Internal record: credentials never leave this module.
type UserRecord = User & { passwordHash?: string; googleId?: string };

// Kept on globalThis so dev hot-reloads don't wipe sign-ups.
// TODO: swap for a real database; the exported functions are the only seam.
const g = globalThis as unknown as { __notelyUsers?: UserRecord[] };
const users: UserRecord[] = (g.__notelyUsers ??= [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
]);

const normalize = (email: string) => email.trim().toLowerCase();

function toUser({ id, email, name, createdAt }: UserRecord): User {
  return { id, email, name, createdAt };
}

export async function listUsers(): Promise<User[]> {
  return users.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const u = users.find((u) => u.id === id);
  return u && toUser(u);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const u = users.find((u) => u.email === normalize(email));
  return u && toUser(u);
}

export class EmailTakenError extends Error {}

export async function createUser(input: {
  email: string;
  name: string;
  password: string;
}): Promise<User> {
  const email = normalize(input.email);
  if (users.some((u) => u.email === email)) throw new EmailTakenError();
  const record: UserRecord = {
    id: randomUUID(),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash: await hash(input.password, 12),
  };
  users.push(record);
  return toUser(record);
}

// Dummy hash so unknown emails cost the same as wrong passwords (timing).
const DUMMY_HASH = "$2b$12$C6UzMDM.H6dfI/f/IKcbaeZK3BQ4ZkQ7G3pYb3S5pY8yB1m6k3oXa";

export async function verifyCredentials(
  email: string,
  password: string,
): Promise<User | null> {
  const u = users.find((u) => u.email === normalize(email));
  const ok = await compare(password, u?.passwordHash ?? DUMMY_HASH);
  return u && u.passwordHash && ok ? toUser(u) : null;
}

// Called only with Google profiles whose email Google reports as verified,
// so linking to an existing account by email is safe.
export async function upsertGoogleUser(profile: {
  googleId: string;
  email: string;
  name?: string | null;
}): Promise<User> {
  const email = normalize(profile.email);
  let u =
    users.find((u) => u.googleId === profile.googleId) ??
    users.find((u) => u.email === email);
  if (!u) {
    u = {
      id: randomUUID(),
      email,
      name: profile.name?.trim() || email.split("@")[0],
      createdAt: new Date().toISOString().slice(0, 10),
    };
    users.push(u);
  }
  u.googleId ??= profile.googleId;
  return toUser(u);
}

// Returns the signed-in user, or undefined when there is no valid session.
export async function getCurrentUser(): Promise<User | undefined> {
  const { auth } = await import("@/auth");
  const session = await auth();
  const id = session?.user?.id;
  return id ? getUser(id) : undefined;
}
