"use server";

import { AuthError } from "next-auth";
import { redirect } from "next/navigation";
import { z } from "zod";
import { signIn, signOut } from "@/auth";
import { createUser, EmailTakenError } from "@/lib/users";

export type FormState = { error?: string } | undefined;

// Only allow same-site relative paths to avoid open redirects.
function safeRedirect(to: FormDataEntryValue | null) {
  return typeof to === "string" && /^\/(?![/\\])/.test(to) ? to : "/dashboard";
}

export async function signInWithCredentials(
  _prev: FormState,
  form: FormData,
): Promise<FormState> {
  try {
    await signIn("credentials", {
      email: form.get("email"),
      password: form.get("password"),
      redirectTo: safeRedirect(form.get("callbackUrl")),
    });
  } catch (e) {
    if (e instanceof AuthError) return { error: "Invalid email or password." };
    throw e; // redirects must propagate
  }
}

export async function signInWithGoogle(form: FormData) {
  await signIn("google", { redirectTo: safeRedirect(form.get("callbackUrl")) });
}

const signUpSchema = z.object({
  name: z.string().trim().min(1, "Name is required."),
  email: z.string().email("Enter a valid email."),
  password: z.string().min(8, "Password must be at least 8 characters.").max(72),
});

export async function signUp(_prev: FormState, form: FormData): Promise<FormState> {
  const parsed = signUpSchema.safeParse(Object.fromEntries(form));
  if (!parsed.success) return { error: parsed.error.issues[0].message };
  try {
    await createUser(parsed.data);
  } catch (e) {
    if (e instanceof EmailTakenError)
      return { error: "An account with that email already exists." };
    throw e;
  }
  await signIn("credentials", {
    email: parsed.data.email,
    password: parsed.data.password,
    redirectTo: "/dashboard",
  });
}

export async function signOutAction() {
  await signOut({ redirectTo: "/" });
}
