const button = "w-full rounded bg-foreground p-2 text-sm font-medium text-background disabled:opacity-60";

export function AuthForm({
  mode,
  action,
  callbackUrl,
}: {
  mode: "signin" | "signup";
  action: (prev: FormState, form: FormData) => Promise<FormState>;
  callbackUrl?: string;
}) {
  const [state, formAction, pending] = useActionState(action, undefined);
  const signup = mode === "signup";

  return (
    <main className="mx-auto w-full max-w-sm space-y-4 p-8">
      <h1 className="text-2xl font-semibold">{signup ? "Create account" : "Sign in"}</h1>

